static unsigned checks=0;
static void check(bool value,const char* label){if(!value)throw std::runtime_error(label);++checks;}
template<class F>void rejects(F f,const char* label){bool bad=false;try{f();}catch(const std::exception&){bad=true;}check(bad,label);}
static QByteArray json(const QJsonObject& o){return QJsonDocument(o).toJson(QJsonDocument::Compact);}
static QString hash(const QByteArray& b){return QString::fromLatin1(underlay::digest(b).toHex());}
static QJsonObject layout(int width=600,int height=800,int font=12){return {{"engine","MuPDF"},{"version","1.28.3"},{"width",width},{"height",height},{"fontSize",font},{"publisherCss",true},{"userCss",""},{"textPolicy","collapse-whitespace-v1"}};}
static QString layoutId(const QJsonObject& value){return "epub-reflow-v1:"+hash(json(value));}
static void write(const Path& p,const QByteArray& b){underlay::privateDirectory(p.parent_path());underlay::atomicFile(p,b);}
